/* Guest GUI/audio integration check; payload is generated by xmms.py. */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <sys/wait.h>
#include <signal.h>
#include <string.h>
#include "blobs.h"
extern int xmms_remote_get_playlist_length(int), xmms_remote_is_playing(int);
extern int xmms_remote_is_paused(int), xmms_remote_get_output_time(int);
extern void xmms_remote_pause(int),xmms_remote_play(int),xmms_remote_stop(int);
extern void xmms_remote_playlist_next(int),xmms_remote_quit(int);
extern void xmms_remote_set_volume(int,int,int),xmms_remote_get_volume(int,int*,int*);
extern void xmms_remote_jump_to_time(int,int);
static int launch(char *const args[]){int p=fork();if(!p){execv(args[0],args);perror("exec");_exit(127);}return p;}
#define REQUIRE(test) do{if(!(test)){printf("XMMS_FAIL: %s\n",#test);fflush(stdout);return 2;}}while(0)
static int time_at_least(int minimum){for(int i=0;i<100;i++){if(xmms_remote_get_output_time(0)>=minimum)return 1;usleep(100000);}return 0;}
int main(void){
 int console=open("/dev/console",O_WRONLY);if(console>=0){dup2(console,1);dup2(console,2);close(console);}
 for(unsigned i=0;i<sizeof(payload)/sizeof(*payload);i++){
  char path[256];strcpy(path,payload[i].name);for(char*p=path+1;*p;p++)if(*p=='/'){*p=0;mkdir(path,0755);*p='/';}
  FILE*f=fopen(path,"wb");REQUIRE(f);REQUIRE(fwrite(payload[i].start,1,payload[i].end-payload[i].start,f)==(size_t)(payload[i].end-payload[i].start));fclose(f);chmod(path,0755);
 }
 mkdir("/tmp/.xmms",0777);chmod("/tmp/.xmms",0777);mkdir("/tmp/.X11-unix",0777);setenv("HOME","/tmp",1);setenv("DISPLAY",":0",1);
 FILE*f=fopen("/tmp/.xmms/config","w");fputs("[xmms]\nshow_wm_decorations=TRUE\nuse_eplugins=FALSE\n",f);fclose(f);chmod("/tmp/.xmms/config",0666);
 ioctl(1,TIOCSFB,(void*)1);
 char*x[]={"/usr/bin/X",":0","-ac",NULL};int server=launch(x);sleep(2);
 REQUIRE(setgid(1000)==0);REQUIRE(setuid(1000)==0);
 char*app[]={"/usr/bin/xmms","/tmp/test.wav","/tmp/test.mp3",NULL};int player=launch(app);printf("XMMS_TEST_PID=%d uid=%d\n",player,getuid());fflush(stdout);
 int ready=0;for(int i=0;i<90;i++){if(xmms_remote_get_playlist_length(0)==2){ready=1;break;}sleep(1);}
 REQUIRE(ready);REQUIRE(time_at_least(500));puts("XMMS_WAV_PLAYING");fflush(stdout);
 xmms_remote_pause(0);REQUIRE(xmms_remote_is_paused(0));usleep(900000);int paused=xmms_remote_get_output_time(0);usleep(500000);REQUIRE(xmms_remote_get_output_time(0)==paused);
 xmms_remote_pause(0);REQUIRE(!xmms_remote_is_paused(0));REQUIRE(time_at_least(paused+300));
 xmms_remote_set_volume(0,35,70);int left,right;xmms_remote_get_volume(0,&left,&right);REQUIRE(left==35&&right==70);
 xmms_remote_stop(0);usleep(200000);REQUIRE(!xmms_remote_is_playing(0));
 xmms_remote_play(0);REQUIRE(time_at_least(300));xmms_remote_jump_to_time(0,3000);REQUIRE(time_at_least(3000));puts("XMMS_RESTART_SEEK_VOLUME_PASS");fflush(stdout);
 xmms_remote_playlist_next(0);REQUIRE(time_at_least(500));puts("XMMS_MP3_PLAYING");fflush(stdout);sleep(2);
 xmms_remote_pause(0);REQUIRE(xmms_remote_is_paused(0));
 xmms_remote_stop(0);usleep(200000);REQUIRE(!xmms_remote_is_playing(0));
 xmms_remote_quit(0);int status;REQUIRE(waitpid(player,&status,0)==player);REQUIRE(WIFEXITED(status)&&WEXITSTATUS(status)==0);
 kill(server,SIGTERM);puts("XMMS_CHECK_PASS");fflush(stdout);return 0;
}
